#!/usr/bin/env python3
"""Exact small-prime verification of the Codex consult claims
(review/codex-consult-residual/proof_text.md), against the lane's definitions:

  unit option set  Opt(U) = {(val T, |T|/2 mod p) : T nonempty, even #refl, |T| even}
  depth(U)         = max d with e_const in span{(m(s))_{deg m < d} : s in Opt(U)}
                     (= exists theta = [0] + sum c_s [s] in J^d; tiling.depth_at_least)
  tiling           = partition of the cyclic word into arcs (top-level blocks);
                     it proves the theorem iff sum depth(block) >= 2p-1 (Lemma G).

Sections: A membership of w_p in Res; B direct solution; C max short-block tiling
depth (all partitions into arcs of length <= Lb, exact block depths) with
counter-controls; D lemma checks.  Usage: verify_consult.py [primes...]
"""
import sys, os, json, random, itertools
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from tiling import unit_points, depth_at_least
import coverage_all as ca

def depth(unit, p):
    pts = unit_points(tuple(unit), p)
    d = 0
    while d <= len(unit) // 2 and depth_at_least(pts, d + 1, p):
        d += 1
    return d

def R(x): return ('R', x)
def F(y): return ('F', y)

def w_family(p, variant='w'):
    if variant == 'w':      # consult w_p
        runs = [('F', 0, p - 2), ('R', 1, p - 2), ('F', 1, p - 2), ('R', 1, p - 2), ('F', 2, 4), ('R', 1, 3)]
    elif variant == 'short_first_rot':   # counter-control: first rotation run p-3
        runs = [('F', 0, p - 2), ('R', 1, p - 3), ('F', 1, p - 2), ('R', 1, p - 2), ('F', 2, 5), ('R', 1, 3)]
    elif variant == 'even_middle':       # counter-control: middle reflection run even
        runs = [('F', 0, p - 2), ('R', 1, p - 2), ('F', 1, p - 1), ('R', 1, p - 2), ('F', 2, 3), ('R', 1, 3)]
    w = []
    for c, v, l in runs:
        w += [(c, v % p)] * l
    assert len(w) == 4 * p - 1
    return w

def lemmaA_max(word, p):
    """max over all zone-sign patterns of the rotation runs and all k of the CD bound."""
    ys, gaps = ca.gaps_of(word)
    runs = [g for g in gaps if g]
    best = -10**9
    for signs in itertools.product((1, -1), repeat=len(runs)):
        signed = [s * x % p for s, g in zip(signs, runs) for x in g]
        for k in range(1, len(signed) + 1):
            best = max(best, ca.lemmaA_bound(signed, k, p))
    return best

def section_A(p, w):
    ys, gaps = ca.gaps_of(w)
    Rn = sum(1 for c, _ in w if c == 'R')
    # odd reflection runs (cyclic)
    n = len(w); s = next(i for i in range(n) if w[i][0] == 'F' and w[i - 1][0] == 'R')
    ww = w[s:] + w[:s]; lens = []; cur = 0
    for c, _ in ww:
        if c == 'F': cur += 1
        elif cur: lens.append(cur); cur = 0
    if cur: lens.append(cur)
    oF = sum(1 for l in lens if l % 2)
    return {'EGZ': Rn >= 3 * p - 1, 'P': ca.tool_P(ys, gaps, p), 'DBL': ca.tool_DBL(ys, gaps, p),
            'DAV': ca.tool_DAV(ys, gaps, p), 'RIGID': ca.tool_RIGID(w, p), 'RPRIME': ca.tool_RPRIME(w, p),
            'T0(oF<=1)': oF <= 1, 'LemmaA_max_bound': lemmaA_max(w, p), 'LemmaA': lemmaA_max(w, p) >= p}

def section_B(p, w):
    # consult's selection: all initial sigma_0, first sigma_1, second rotation run, final 3 rotations
    idx = list(range(0, p - 2)) + [2 * (p - 2)] + list(range(3 * (p - 2), 4 * (p - 2))) + list(range(4 * p - 4, 4 * p - 1))
    v, e = 0, 1
    for i in idx:
        c, x = w[i]
        v = (v + e * x) % p
        if c == 'F': e = -e
    return {'size': len(idx), 'increasing': idx == sorted(idx), 'product': (v, e), 'dp_exists': ca.has_solution(w, p)}

def max_tiling_depth(w, p, Lb):
    n = len(w)
    cache = {}
    def bd(s, L):
        key = (s, L)
        if key not in cache:
            cache[key] = depth([w[(s + i) % n] for i in range(L)], p)
        return cache[key]
    best = -1
    for cut in range(n):
        dp = [-10**9] * (n + 1); dp[0] = 0
        for i in range(n):
            if dp[i] < 0: continue
            for L in range(1, Lb + 1):
                if i + L > n: break
                val = dp[i] + bd((cut + i) % n, L)
                if val > dp[i + L]: dp[i + L] = val
        best = max(best, dp[n])
    return best

def section_D(p, rng):
    out = {}
    # four-letter classification, exhaustive up to translation (a=0) and scaling
    def norm_iter(k):
        for vals in itertools.product(range(p), repeat=k):
            nz = [v for v in vals if v]
            if nz and nz[0] != 1: continue
            yield vals
    bad = Counter4 = {'frrf': 0, 'rfrf': 0, 'frfr': 0, 'fixed_shapes_nonfull': 0}
    for C, x, z in norm_iter(3):
        S = (x + z) % p
        for shape, unit, pred in [
            ('frrf', [F(0), R(x), R(z), F(-C)], C == S and C != 0),
            ('rfrf', [R(x), F(0), R(z), F(-C)], C == S and z != 0),
            ('frfr', [F(0), R(x), F(-C), R(z)], C == S and x != 0)]:
            nonfull = depth(unit, p) < 2
            if nonfull != pred: bad[shape] += 1
    for vals in itertools.product(range(p), repeat=4) if p <= 7 else [tuple(rng.randrange(p) for _ in range(4)) for _ in range(3000)]:
        a, b, c, d = vals
        for unit in ([R(a), R(b), R(c), R(d)], [F(a), F(b), F(c), F(d)], [R(a), R(b), F(c), F(d)],
                     [F(a), F(b), R(c), R(d)], [R(a), F(b), F(c), R(d)]):
            if depth(unit, p) < 2: bad['fixed_shapes_nonfull'] += 1
    out['four_letter_mismatches'] = bad
    # constant-rotation bracket formula
    mism = 0; checked = 0
    for n_ in range(1, min(2 * p - 2, 12) + 1):
        m = n_ // 2
        for x in (0, 1):
            for C in range(p):
                unit = [F(0)] + [R(x)] * n_ + [F(-C)]
                full = depth(unit, p) >= m + 1
                pred = (x == 0) or (C % p not in {((4 * j - 2) * x) % p for j in range(1, m + 1)})
                checked += 1; mism += (full != pred)
    out['constant_bracket'] = {'checked': checked, 'mismatches': mism}
    # four arbitrary rotations between reflections
    mism = 0; checked = 0
    for C in range(p):
        for xs in itertools.combinations_with_replacement(range(p), 4):
            if p > 7 and rng.random() > 0.15: continue
            unit = [F(0)] + [R(x) for x in xs] + [F(-C)]
            full = depth(unit, p) >= 3
            allx = len(set(xs)) == 1 and xs[0] != 0
            pred = not (allx and C % p in {(2 * xs[0]) % p, (6 * xs[0]) % p})
            checked += 1; mism += (full != pred)
    out['four_rotation_bracket'] = {'checked': checked, 'mismatches': mism}
    # six-letter universal shapes
    shapes = {'FRRFFF': 'FRRFFF', 'FFFRRF': 'FFFRRF', 'FRFFRF': 'FRFFRF'}
    res6 = {}
    for name, sh in shapes.items():
        nonfull = 0; tot = 0
        it = itertools.product(range(p), repeat=6) if p <= 5 else (tuple(rng.randrange(p) for _ in range(6)) for _ in range(4000))
        for vals in it:
            unit = [(c, v) for c, v in zip(sh, vals)]
            tot += 1; nonfull += depth(unit, p) < 3
        res6[name] = {'tested': tot, 'nonfull': nonfull, 'exhaustive': p <= 5}
    out['six_letter'] = res6
    # eight-letter degenerate unit
    out['sigma0_rho1^4_sigma-6^3_depth'] = depth([F(0)] + [R(1)] * 4 + [F(-6)] * 3, p)
    # insertion lemma
    viol = 0
    for _ in range(300):
        L = rng.randrange(2, 7)
        U = [(rng.choice('RF'), rng.randrange(p)) for _ in range(L)]
        d0 = depth(U, p)
        pos = rng.randrange(0, L + 1)
        if rng.random() < 0.5:
            v = rng.randrange(p); ins = [R(v), R(-v % p)]
        else:
            y = rng.randrange(p); ins = [F(y), F(y)]
        if depth(U[:pos] + ins + U[pos:], p) < d0 + 1: viol += 1
    out['insertion_violations_of_300'] = viol
    return out

def main():
    primes = [int(a) for a in sys.argv[1:]] or [5, 7, 11, 13]
    rng = random.Random(20261017)
    report = {}
    for p in primes:
        r = {}
        w = w_family(p)
        r['A_membership_tools_true'] = section_A(p, w)
        r['B_direct_solution'] = section_B(p, w)
        r['C_max_depth_blocks_lt_p'] = max_tiling_depth(w, p, p - 1)
        r['C_target'] = 2 * p - 1
        r['C_max_depth_blocks_le_p'] = max_tiling_depth(w, p, p)
        for var in ('short_first_rot', 'even_middle'):
            wv = w_family(p, var)
            r['C_counter_' + var + '_blocks_lt_p'] = max_tiling_depth(wv, p, p - 1)
        if p <= 11:
            r['D_lemmas'] = section_D(p, rng)
        report[p] = r
        print(p, json.dumps(r), flush=True)
    json.dump(report, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'evidence', 'consult_verification.json'), 'w'), indent=1)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
r"""Group-algebra tiling criterion for ordered EGZ in D_{2p} (sufficient condition).

Unit = consecutive segment of the cyclic word.  S_u = {(value, size/2) in Z_p^2 :
internal selections with an even number of reflections and even size}; 0 in S_u.
depth(S_u) >= d  iff  e_const is in the span of {(m(a))_{deg m < d} : a in S_u \ {0}}
(i.e. exists c with c_0 = -1 ... element of J^d in F_p[Z_p^2]).  If the cyclic word is
partitioned into units with total depth >= 2p-1 (Loewy length of F_p[Z_p^2]), an
identity 2p-subword exists (proof: product of the unit elements is 0; coefficient of
[0] gives a nonempty zero-sum choice; even #F per unit keeps zones; half-size = p).
depth <= floor(len/2); "full" = equality.  Criterion used here: one odd unit of
length 1 or 3 (always full) + even full units of length <= LMAX.
Usage: tiling.py p nwords seed mode   (modes as in coverage_all.py)  or  tiling.py p "word"
"""
import sys, random, itertools, json
from functools import lru_cache
from collections import Counter

P = None

def unit_points(unit, p):
    """unit: tuple of ('R'|'F', val). Return set of (value, half) for nonempty
    selections with even #F and even size."""
    n = len(unit)
    pts = set()
    for mask in range(1, 1 << n):
        nf = 0; sz = 0; e = 1; v = 0
        for i in range(n):
            if mask >> i & 1:
                c, x = unit[i]
                sz += 1
                v = (v + e * x) % p
                if c == 'F':
                    nf += 1; e = -e
        if nf % 2 == 0 and sz % 2 == 0:
            pts.add((v, (sz // 2) % p))
    return pts

def rank_mod(rows, p):
    rows = [list(r) for r in rows]
    rk = 0; ncol = len(rows[0]) if rows else 0
    for col in range(ncol):
        piv = None
        for i in range(rk, len(rows)):
            if rows[i][col] % p:
                piv = i; break
        if piv is None:
            continue
        rows[rk], rows[piv] = rows[piv], rows[rk]
        inv = pow(rows[rk][col], p - 2, p)
        rows[rk] = [x * inv % p for x in rows[rk]]
        for i in range(len(rows)):
            if i != rk and rows[i][col] % p:
                f = rows[i][col]
                rows[i] = [(a - f * b) % p for a, b in zip(rows[i], rows[rk])]
        rk += 1
    return rk

def depth_at_least(pts, d, p):
    """True iff e_const in span of evaluation vectors of monomials deg<d at pts."""
    if d <= 0:
        return True
    mons = [(i, j) for i in range(d) for j in range(d) if i + j < d]
    vecs = [[pow(a, i, p) * pow(h, j, p) % p for (i, j) in mons] for (a, h) in pts]
    e0 = [1 if (i, j) == (0, 0) else 0 for (i, j) in mons]
    if not vecs:
        return False
    r1 = rank_mod(vecs, p)
    r2 = rank_mod(vecs + [e0], p)
    return r1 == r2

@lru_cache(maxsize=None)
def full_unit(unit, p):
    L = len(unit)
    if L % 2:
        return False
    nf = sum(1 for c, _ in unit if c == 'F')
    if nf % 2:
        return False
    pts = unit_points(unit, p)
    return depth_at_least(pts, L // 2, p)

def tiles(word, p, lmax=8):
    """Search: cyclic word; choose odd unit (length 1 or 3) start s; tile the rest."""
    n = len(word)
    for olen in (1, 3):
        for s in range(n):
            lin = [word[(s + olen + i) % n] for i in range(n - olen)]
            m = len(lin)
            ok = [False] * (m + 1)
            ok[0] = True
            for i in range(m):
                if not ok[i]:
                    continue
                for L in range(2, lmax + 1, 2):
                    if i + L <= m and not ok[i + L]:
                        if full_unit(tuple(lin[i:i + L]), p):
                            ok[i + L] = True
            if ok[m]:
                return True
    return False

def parse(s):
    return [('R' if t[0] == 'r' else 'F', int(t[1:])) for t in s.split()]

def main():
    p = int(sys.argv[1])
    if len(sys.argv) == 3:
        w = parse(sys.argv[2]); print(tiles(w, p)); return
    nw = int(sys.argv[2]); seed = int(sys.argv[3]); mode = sys.argv[4]
    import coverage_all as ca
    import residual_stats as rs
    rng = random.Random(seed)
    N = 4 * p - 1
    st = Counter(); fails = []
    for it in range(nw):
        if mode in ('rotrigid', 'twoval', 'gr'):
            w = rs.make(mode, p, N, rng)
        elif mode == 'random':
            pr = rng.random()
            w = [('R', rng.randrange(p)) if rng.random() < pr else ('F', rng.randrange(p)) for _ in range(N)]
        elif mode == 'rigid':
            pr = rng.random()
            w = [('R', rng.choice([1, p - 1])) if rng.random() < pr else ('F', 0) for _ in range(N)]
        else:
            raise SystemExit('mode')
        t = tiles(w, p)
        res = ca.classify(w, p)
        old = any(res.values())
        st['tile' if t else 'notile'] += 1
        st[('old' if old else 'noold') + '_' + ('tile' if t else 'notile')] += 1
        if not t and not old and len(fails) < 10:
            fails.append(' '.join(('r%d' if c == 'R' else 's%d') % v for c, v in w))
    print(json.dumps({'p': p, 'mode': mode, 'n': nw, 'stats': dict(st)}))
    for f in fails:
        print('BOTHFAIL', f)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Which proved sufficient conditions cover a word of length 4p-1 over D_{2p}?

Word: list of ('R', x) / ('F', y), x,y in Z_p.  Left convention
(v,e)(v',e') = (v + e v', e e').  Tools (see proof-dihedral-partial.md):
  EGZ       R >= 3p-1
  P         F + sum floor(n_t/2) >= 3p-1                       (Theorem P)
  DBL       packed-stretch Doubling Lemma, exact subset search
  DAV       Davenport-alpha items >= 3p-1
  RIGID     all letters in {rho_x, rho_-x, sigma_y}
  RPRIME    Corollary R' (<= p-3 merge-free defects)
  LA        Lemma A: some reflection set Phi (even, colouring) with
            sum_g min(k, mu(g)) - k + 1 >= p, k = 2p - |Phi| (searched over
            all Phi with |Phi| <= phimax, or random sample)
Also: exact DP existence check (has_solution) for uncovered words.
Usage: coverage_all.py p nwords seed [mode]
  mode: random | nearrigid:<defects>
"""
import sys, random, json, itertools
from collections import Counter

def gaps_of(word):
    """Rotate so word ends with a reflection; return (ys, gaps) where gaps[t] is the
    list of rotation values before reflection t (cyclic)."""
    idx = [i for i, (c, _) in enumerate(word) if c == 'F']
    if not idx:
        return None, None
    last = idx[-1]
    w = word[last + 1:] + word[:last + 1]
    ys, gaps, cur = [], [], []
    for c, v in w:
        if c == 'R':
            cur.append(v)
        else:
            gaps.append(cur); ys.append(v); cur = []
    return ys, gaps

def has_solution(word, p):
    """Exact DP over the linear word: states (size, sign, value)."""
    n2 = 2 * p
    # state: dict (size, e) -> set of v ; product so far (v, e)
    reach = {(0, 1): {0}}
    for c, val in word:
        new = {k: set(s) for k, s in reach.items()}
        for (sz, e), vs in reach.items():
            if sz >= n2:
                continue
            if c == 'R':
                key = (sz + 1, e)
                tgt = new.setdefault(key, set())
                for v in vs:
                    tgt.add((v + e * val) % p)
            else:
                key = (sz + 1, -e)
                tgt = new.setdefault(key, set())
                for v in vs:
                    tgt.add((v + e * val) % p)
        reach = new
    return 0 in reach.get((n2, 1), set())

def tool_P(ys, gaps, p):
    F = len(ys)
    return F + sum(len(g) // 2 for g in gaps) >= 3 * p - 1

def bracket(ys, gaps, t, p):
    F = len(ys)
    return (ys[(t - 1) % F] - ys[t] - sum(gaps[t])) % p

def subset_sum_exact(pool, need, target, p):
    if need < 0:
        return False
    if need == 0:
        return target % p == 0
    if len(pool) < need:
        return False
    # dp[c] = bitmask set of sums reachable with c elements
    dp = [0] * (need + 1)
    dp[0] = 1
    full = (1 << p) - 1
    for x in pool:
        x %= p
        for c in range(min(need, len(pool)), 0, -1):
            s = dp[c - 1]
            if s:
                rot = ((s << x) | (s >> (p - x))) & full if x else s
                dp[c] |= rot
    return bool((dp[need] >> (target % p)) & 1)

def tool_DBL(ys, gaps, p):
    F = len(ys)
    for t0 in range(F):
        for j in range(0, (F - 1) // 2 + 1):
            if 2 * j + 1 > F:
                break
            Ms = [(t0 + 2 * i - 1) % F for i in range(1, j + 1)]
            Ps = [(t0 + 2 * i) % F for i in range(0, j + 1)]
            need = p - 2 * j - sum(len(gaps[t]) for t in Ms)
            if need < 0:
                break
            bsum = sum(bracket(ys, gaps, t, p) for t in Ms) % p
            pool = [x for t in Ps for x in gaps[t]]
            if subset_sum_exact(pool, need, (-bsum) % p, p):
                return True
    return False

def tool_DAV(ys, gaps, p):
    F = len(ys)
    R = sum(len(g) for g in gaps)
    w = [1 - len(g) for g in gaps]   # gain of putting gap t into I
    # max weight independent set on cycle C_F (F>=1); only positive weights matter
    best = 0
    if F == 1:
        best = max(0, w[0])
    else:
        for first_in in (False, True):
            # linear DP over 0..F-1 with constraint on gap 0 and wraparound
            inc, exc = (w[0] if first_in else -10**9), (0 if not first_in else -10**9)
            for t in range(1, F):
                if t == F - 1 and first_in:
                    inc, exc = -10**9, max(inc, exc)
                else:
                    inc, exc = exc + w[t], max(inc, exc)
            best = max(best, inc, exc)
    return R + best >= 3 * p - 1

def templates(word, p):
    rv = Counter(v for c, v in word if c == 'R')
    fv = Counter(v for c, v in word if c == 'F')
    xs = set()
    for v in rv:
        if v % p:
            xs.add(min(v % p, (-v) % p))
    if not xs:
        xs = {1}
    ys = set(fv) if fv else {0}
    return xs, ys

def is_template(c, v, x, y, p):
    if c == 'R':
        return v % p in (x % p, (-x) % p)
    return v % p == y % p

def tool_RIGID(word, p):
    xs, ys = templates(word, p)
    for x in xs:
        for y in ys:
            if all(is_template(c, v, x, y, p) for c, v in word):
                return True
    return False

def tool_RPRIME(word, p):
    xs, ys = templates(word, p)
    n = len(word)
    for x in xs:
        for y in ys:
            defects = [i for i, (c, v) in enumerate(word) if not is_template(c, v, x, y, p)]
            if len(defects) > p - 3:
                continue
            # refined merge condition: every maximal run of template rotations in
            # w - Delta containing >= p equal letters lies inside one gap of w
            dset = set(defects)
            sub = [(i, word[i]) for i in range(n) if i not in dset]
            ok = True
            if any(c == 'F' for _, (c, _) in sub):
                last = max(k for k, (_, (c, _)) in enumerate(sub) if c == 'F')
                sub = sub[last + 1:] + sub[:last + 1]
                run = []
                for i, (c, v) in sub:
                    if c == 'R':
                        run.append((i, v % p))
                        continue
                    if run:
                        cnt = Counter(val for _, val in run)
                        if max(cnt.values()) >= p:
                            a, b = run[0][0], run[-1][0]
                            span = range(a + 1, b) if a <= b else list(range(a + 1, n)) + list(range(0, b))
                            if any(word[k][0] == 'F' for k in span):
                                ok = False
                                break
                    run = []
            if ok:
                return True
    return False

def lemmaA_bound(signed, k, p):
    mu = Counter(v % p for v in signed)
    return sum(min(k, m) for m in mu.values()) - k + 1

def tool_LA(ys, gaps, p, phimax=None, samples=4000, rng=None):
    """Search reflection subsets Phi (even size) for the Lemma A CD bound."""
    F = len(ys)
    R = sum(len(g) for g in gaps)
    def check(Phi):
        k = 2 * p - len(Phi)
        if k < 1 or k > R:
            return False
        # zones: gap t sign = (-1)^{#Phi among reflections before gap t}, cyclic start at gap 0
        sgn, signed = 1, []
        Phis = set(Phi)
        for t in range(F):
            for x in gaps[t]:
                signed.append(sgn * x)
            if t in Phis:
                sgn = -sgn
        return lemmaA_bound(signed, k, p) >= p
    if phimax is None:
        phimax = F
    # exhaustive for small F, else random
    total = sum(1 for _ in range(0))
    if F <= 16:
        for size in range(2, min(F, phimax, 2 * p) + 1, 2):
            for Phi in itertools.combinations(range(F), size):
                if check(Phi):
                    return True
        return False
    rng = rng or random.Random(0)
    for _ in range(samples):
        size = rng.randrange(2, min(F, 2 * p) + 1, 2)
        Phi = rng.sample(range(F), size)
        if check(Phi):
            return True
    return False

def classify(word, p, la=True):
    R = sum(1 for c, _ in word if c == 'R')
    res = {}
    res['EGZ'] = R >= 3 * p - 1
    ys, gaps = gaps_of(word)
    if ys is None:
        res.update(P=False, DBL=False, DAV=False, LA=False)
    else:
        res['P'] = tool_P(ys, gaps, p)
        res['DBL'] = tool_DBL(ys, gaps, p)
        res['DAV'] = tool_DAV(ys, gaps, p)
        res['LA'] = tool_LA(ys, gaps, p) if la else False
    res['RIGID'] = tool_RIGID(word, p)
    res['RPRIME'] = tool_RPRIME(word, p)
    return res

def wstr(word):
    return ' '.join(('r%d' if c == 'R' else 's%d') % v for c, v in word)

def main():
    p = int(sys.argv[1]); nw = int(sys.argv[2]); seed = int(sys.argv[3])
    mode = sys.argv[4] if len(sys.argv) > 4 else 'random'
    rng = random.Random(seed)
    N = 4 * p - 1
    stats = Counter(); unc = []
    for it in range(nw):
        if mode == 'random':
            pr = rng.random()
            word = [('R', rng.randrange(p)) if rng.random() < pr else ('F', rng.randrange(p)) for _ in range(N)]
        elif mode.startswith('nearrigid'):
            nd = int(mode.split(':')[1])
            pr = rng.random()
            word = [('R', rng.choice([1, p - 1])) if rng.random() < pr else ('F', 0) for _ in range(N)]
            for _ in range(nd):
                i = rng.randrange(N)
                word[i] = ('R', rng.randrange(p)) if rng.random() < 0.5 else ('F', rng.randrange(p))
        elif mode.startswith('lowval'):
            # values from a small set: rotations in {+-1,+-2}, reflections in {0,1}
            pr = rng.random()
            word = [('R', rng.choice([1, p - 1, 2, p - 2])) if rng.random() < pr else ('F', rng.choice([0, 1])) for _ in range(N)]
        elif mode.startswith('rotrigid'):
            pr = rng.uniform(0.25, 0.6)
            word = [('R', rng.choice([1, p - 1])) if rng.random() < pr else ('F', rng.randrange(p)) for _ in range(N)]
        elif mode.startswith('reflrigid'):
            pr = rng.uniform(0.25, 0.75)
            word = [('R', rng.randrange(1, p)) if rng.random() < pr else ('F', 0) for _ in range(N)]
        elif mode.startswith('twoval'):
            c = rng.randrange(1, p)
            pr = rng.uniform(0.25, 0.6)
            word = [('R', rng.choice([1, p - 1])) if rng.random() < pr else ('F', rng.choice([0, c])) for _ in range(N)]
        elif mode.startswith('gr'):
            # generalized rigid: rotations +-1, reflection runs constant with random values
            pr = rng.uniform(0.25, 0.6)
            word, prevF, cur = [], False, rng.randrange(p)
            for _ in range(N):
                if rng.random() < pr:
                    word.append(('R', rng.choice([1, p - 1]))); prevF = False
                else:
                    if not prevF:
                        cur = rng.randrange(p) if rng.random() < 0.5 else 0
                    word.append(('F', cur)); prevF = True
        res = classify(word, p)
        covered = [k for k, v in res.items() if v]
        if covered:
            stats['covered'] += 1
            for k in covered:
                stats['by_' + k] += 1
        else:
            stats['uncovered'] += 1
            sol = has_solution(word, p)
            stats['uncovered_solvable' if sol else 'COUNTEREXAMPLE'] += 1
            if len(unc) < 40:
                unc.append(wstr(word))
    print(json.dumps({'p': p, 'n': nw, 'seed': seed, 'mode': mode, 'stats': dict(stats)}))
    for u in unc[:40]:
        print('UNC', u)

if __name__ == '__main__':
    main()

